.board-error button {
    margin-top: 0.5rem;
    padding: 0.4rem 1rem;
    background: #dc2626;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

/* Summary bar */
.summary-bar {
    display: flex;
    gap: 1rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.summary-stat {
    background: #f9fafb;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 0.75rem 1.25rem;
    text-align: center;
    flex: 1;
    min-width: 100px;
}

.summary-stat .stat-value {
    display: block;
    font-size: 1.5rem;
    font-weight: 700;
    color: #111827;
}

.summary-stat .stat-label {
    font-size: 0.8rem;
    color: #6b7280;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.stat-overdue .stat-value {
    color: #dc2626;
}

/* Search bar */
.search-bar {
    margin-bottom: 1rem;
}

.search-bar input {
    width: 100%;
    padding: 0.6rem 1rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
